package org.sigf;
import org.sigf.app.*; import org.sigf.config.*; import org.sigf.security.*; import org.sigf.services.*; import org.sigf.ui.*; import org.sigf.domain.*;

import javafx.application.Platform;import javafx.scene.control.*;import javafx.stage.Stage;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="SIGF_FIRST_RUN_GUI_TEST",matches="true")
class FirstRunTest {
 static void fx(Runnable r)throws Exception{CountDownLatch done=new CountDownLatch(1);AtomicReference<Throwable> err=new AtomicReference<>();Platform.runLater(()->{try{r.run();}catch(Throwable e){err.set(e);}finally{done.countDown();}});assertTrue(done.await(10,TimeUnit.SECONDS));if(err.get()!=null)throw new AssertionError(err.get());}
 static void waitFor(Stage stage,String id)throws Exception{AtomicBoolean found=new AtomicBoolean();for(int i=0;i<150&&!found.get();i++){Thread.sleep(100);fx(()->found.set(stage.getScene().lookup(id)!=null));}assertTrue(found.get(),"No apareció "+id);}
 @Test void emptyDatabaseCreatesAdministratorAndPersists()throws Exception{CountDownLatch started=new CountDownLatch(1);AtomicReference<Stage> ref=new AtomicReference<>();AtomicReference<Main> app=new AtomicReference<>();Platform.startup(()->{try{Stage stage=new Stage();Main main=new Main();main.start(stage);app.set(main);ref.set(stage);}finally{started.countDown();}});assertTrue(started.await(10,TimeUnit.SECONDS));Stage stage=ref.get();assertNotNull(stage);fx(()->{((TextField)stage.getScene().lookup("#dbPort")).setText("55439");((TextField)stage.getScene().lookup("#dbUser")).setText("sigftest");((PasswordField)stage.getScene().lookup("#dbPassword")).setText("test-only");((Button)stage.getScene().lookup("#connectButton")).fire();});waitFor(stage,"#adminUser");fx(()->{((TextField)stage.getScene().lookup("#adminUser")).setText("admin_prueba");((PasswordField)stage.getScene().lookup("#adminPassword")).setText("contraseñaPrueba123");((PasswordField)stage.getScene().lookup("#adminConfirm")).setText("contraseñaPrueba123");Button b=(Button)stage.getScene().getRoot().lookupAll(".button").stream().filter(n->n instanceof Button && ((Button)n).getText().equals("Crear administrador")).findFirst().orElseThrow();b.fire();});waitFor(stage,"#login");fx(()->{((TextField)stage.getScene().lookup("#username")).setText("admin_prueba");((PasswordField)stage.getScene().lookup("#password")).setText("contraseñaPrueba123");((Button)stage.getScene().lookup("#login")).fire();});AtomicReference<javafx.scene.Node> profileName=new AtomicReference<>();for(int i=0;i<150&&profileName.get()==null;i++){Thread.sleep(100);fx(()->javafx.stage.Window.getWindows().stream().filter(javafx.stage.Window::isShowing).map(w->w.getScene()==null?null:w.getScene().lookup("#profileName")).filter(java.util.Objects::nonNull).findFirst().ifPresent(profileName::set));}assertNotNull(profileName.get(),"No apareció la configuración inicial");fx(()->{((TextField)profileName.get()).setText("Farmacia Inicial");javafx.scene.Scene dialogScene=profileName.get().getScene();((TextField)dialogScene.lookup("#profileRuc")).setText("J0000000000000");((Button)dialogScene.lookup("#profileSave")).fire();});AtomicBoolean workspace=new AtomicBoolean();for(int i=0;i<150&&!workspace.get();i++){Thread.sleep(100);fx(()->workspace.set(stage.getScene().getRoot() instanceof javafx.scene.layout.BorderPane));}assertTrue(workspace.get(),"No se abrió el área de trabajo");fx(()->{stage.close();app.get().stop();});try(Database db=new Database("jdbc:postgresql://127.0.0.1:55439/sigf_javafx_db","sigftest","test-only")){assertTrue(new Security(db).hasUsers());assertEquals("Farmacia Inicial",new PharmacyProfileService(db).load().orElseThrow().name());assertEquals("admin_prueba",new Security(db).login("admin_prueba","contraseñaPrueba123").name());}Platform.exit();}
}

